using System.Collections;
using UnityEngine;
using UnityEngine.UI;
using Core;

namespace UI
{
    /// <summary>
    /// 热更新加载界面。
    /// 游戏启动时显示进度条，等待 Addressables 热更下载完成（至少 2 秒），
    /// 完成后隐藏 Slider 和背景图，启用开始按钮。
    /// </summary>
    public class HotfixLoadingUI : MonoBehaviour
    {
        [Header("UI 引用")]
        [SerializeField] private Slider progressBar;
        [SerializeField] private Text progressText;
        [SerializeField] private GameObject backgroundImage;

        [Header("开始按钮（下载完成前禁用）")]
        [SerializeField] private Button startButton;

        [Header("最小显示时长（秒）")]
        [SerializeField] private float minDisplayTime = 2f;

        private void Start()
        {
            // 初始状态：显示进度条和背景，禁用开始按钮
            SetVisible(true);
            if (startButton != null)
                startButton.interactable = false;
            if (progressBar != null)
                progressBar.value = 0f;

            StartCoroutine(WaitForUpdateComplete());
        }

        private IEnumerator WaitForUpdateComplete()
        {
            float startTime = Time.time;

            // 等待热更完成（devMode 下瞬间完成）
            while (!AddressablesUpdater.IsUpdateComplete)
            {
                float progress = AddressablesUpdater.DownloadProgress;
                UpdateProgressUI(progress);
                yield return null;
            }

            // 热更已完成，确保进度条显示 100%
            UpdateProgressUI(1f);

            // 保证最小显示时长（至少 2 秒）
            float elapsed = Time.time - startTime;
            if (elapsed < minDisplayTime)
            {
                yield return new WaitForSeconds(minDisplayTime - elapsed);
            }

            // 隐藏进度条和背景图，启用开始按钮
            SetVisible(false);
            if (startButton != null)
                startButton.interactable = true;
        }

        private void UpdateProgressUI(float progress)
        {
            if (progressBar != null)
                progressBar.value = Mathf.Clamp01(progress);

            if (progressText != null)
            {
                if (AddressablesUpdater.State == AddressablesUpdater.UpdateState.Downloading)
                {
                    var mb = AddressablesUpdater.TotalDownloadBytes / 1024f / 1024f;
                    progressText.text = $"下载资源中 {mb:F1}MB  ({progress * 100:F0}%)";
                }
                else if (AddressablesUpdater.State == AddressablesUpdater.UpdateState.Complete)
                {
                    progressText.text = "加载完成";
                }
                else
                {
                    progressText.text = "加载中...";
                }
            }
        }

        private void SetVisible(bool visible)
        {
            if (progressBar != null)
                progressBar.gameObject.SetActive(visible);
            if (backgroundImage != null)
                backgroundImage.SetActive(visible);
        }
    }
}

using Core;
using UnityEngine;
using XLua;

public class LuaEnvManager
{
  private static LuaEnvManager _instance;
  public static LuaEnvManager Instance =>
      _instance ??= new LuaEnvManager();

  public LuaEnv LuaEnv { get; private set; }

  // 自定义 Loader：通过 Addressables 加载 Lua 脚本（支持远程热更）
  public void Init()
  {
    LuaEnv = new LuaEnv();
    LuaEnv.AddLoader(CustomLoader);
    Debug.Log("[LuaEnvManager] Lua 环境初始化完成");
  }

  private byte[] CustomLoader(ref string filePath)
  {
    // Lua require 用 . 分隔模块路径，需转换为目录分隔符
    string relativePath = filePath.Replace('.', '/');

    // 通过 Addressables 加载（远程热更 bundle 优先于本地包体）
    var resAsset = AssetLoader.TryLoadAsset<TextAsset>("Lua/" + relativePath);
    if (resAsset == null)
      resAsset = AssetLoader.TryLoadAsset<TextAsset>("Lua/" + relativePath + ".lua");
    if (resAsset != null)
    {
      Debug.Log($"[LuaEnvManager] 从 Addressables 加载: {filePath}");
      return resAsset.bytes;
    }

    Debug.LogWarning($"[LuaEnvManager] 无法找到 Lua 文件: {filePath}");
    return null;
  }

  public void Dispose()
  {
    LuaEnv?.Dispose();
    LuaEnv = null;
    _instance = null;
  }
}

